def cvcontent(lang):
 if lang=='en':
  return '''<section class="content-section">{head}<div class="two-column-prose"><h2>Quantitative Data Scientist<br>Credit Risk Modeling</h2><div><p class="micro muted">MIFEL · MEXICO · NOV 2025 — MAY 2026</p><p>Built Mifel’s first end-to-end customer-traceability architecture, bringing origination, credit-bureau and sociodemographic data into a unified customer-level dataset for risk modeling, portfolio monitoring and credit decisions.</p><p>Developed the bank’s first in-house credit-card origination scoring engine with XGBoost and Random Forest; evaluated thousands of hyperparameter configurations through cross-validation and improved risk discrimination by approximately 10 Gini points against the baseline models.</p><p>Worked with engineering teams on a real-time production scoring API; applied reject inference, developed longitudinal behaviour variables and automated monthly portfolio snapshots and risk-monitoring pipelines, reducing manual reporting effort by approximately 50%.</p><p>Developed cohort-based validation frameworks and implemented SHAP explainability to support model monitoring and credit-approval policy updates.</p></div></div></section><section class="content-section"><div class="two-column-prose"><h2>Data Science Associate</h2><div><p class="micro muted">GRUPO SALINAS / TREND IT · MEXICO · MAR 2025 — NOV 2025</p><p>Designed and productionized analytical workflows in Google Cloud Platform for large-scale financial and commercial datasets.</p><p>Built a hybrid recommender system combining Word2Vec embeddings, similarity retrieval, ranking logic and business constraints, evaluated with NDCG@K and Recall@K.</p><p>Built time-series forecasting pipelines with automated retraining and drift monitoring, and implemented a natural-language analytics assistant integrating BigQuery and LookerML.</p><p>Automated campaign-analysis and reporting workflows, reducing manual operational effort by more than 80% while improving reproducibility and auditability.</p></div></div></section><section class="content-section"><div class="two-column-prose"><h2>Future Ready Program<br>Oracle Finance</h2><div><p class="micro muted">PWC MEXICO · MEXICO · AUG 2024 — JAN 2025</p><p>Contributed to Oracle Cloud Finance implementations, supporting process standardization, structured data flows and finance-related automation.</p><p>Supported process automation through scripting, structured queries and operational-data validation.</p></div></div></section><section class="content-section"><div class="two-column-prose"><h2>Risk Department Intern</h2><div><p class="micro muted">ASSOCIATION OF MEXICAN INSURANCE INSTITUTIONS (AMIS) · MEXICO · JUL 2023 — FEB 2024</p><p>Automated risk-report generation in Python, reducing reporting time by 40%.</p><p>Standardized SQL reporting logic for internal risk indicators and monitoring results.</p></div></div></section><section class="content-section">{education}<div class="two-column-prose"><h2>Bachelor’s degree in Actuarial Science</h2><div><p class="micro muted">UNIVERSIDAD LA SALLE</p><p>Academic training in actuarial science.</p></div></div></section><section class="content-section">{technical}<div class="two-column-prose"><h2>Quantitative data practice</h2><div><p><strong>Programming</strong><br>Python (production level), SQL, R and C++.</p><p><strong>Machine learning & statistical modeling</strong><br>Ensemble methods, cross-validation, model selection, reject inference, feature engineering, SHAP, Word2Vec and ranking embeddings.</p><p><strong>Quantitative & financial methods</strong><br>Monte Carlo simulation, stochastic processes, time-series models, portfolio optimization, factor modeling, backtesting, scenario analysis, credit-risk modeling, scorecards, VaR, CVaR and stress testing.</p><p><strong>Tools & platforms</strong><br>NumPy, Pandas, scikit-learn, Statsmodels, TensorFlow, Keras, PyMC, QuantLib, Backtrader, Zipline, Git, GitHub, Jupyter, VS Code, AWS, GCP, BigQuery, Vertex AI and LookerML.</p><p><strong>Languages</strong><br>English — C1.</p></div></div></section><section class="content-section">{training}<div class="two-column-prose"><h2>Courses & credentials</h2><div><p>Deep Learning for Finance — Colegio de Matemáticas Bourbaki</p><p>Mathematical Methods for Quantitative Finance (in progress) — MITx</p><p>Stochastic Processes for Finance — Asociación Mexicana de Actuarios (AMAT)</p><p>Advanced Natural Language Processing; Financial Applications of Machine Learning & AI — Colegio de Matemáticas Bourbaki</p><p>Data Science & Machine Learning for Data Scientists — Tecnológico de Monterrey</p><p>AWS Academy Machine Learning Foundations; Data Analyst in Python — DataCamp</p></div></div></section><section class="content-section">{links}<div class="two-column-prose"><h2>Links pending review</h2><div><p>Public professional links and a downloadable CV will be added after final review.</p><p class="editorial-note">No public contact details are included on this page.</p></div></div></section>'''.format(head=sectionhead('01','Professional experience','FINANCIAL SERVICES'), education=sectionhead('02','Education','ACADEMIC BACKGROUND'), technical=sectionhead('03','Technical areas & languages','TOOLS / METHODS'), training=sectionhead('04','Additional training','CONTINUING EDUCATION'), links=sectionhead('05','Links','PENDING REVIEW'))
 return '''<section class="content-section">{head}<div class="two-column-prose"><h2>Científico de Datos Cuantitativo<br>Modelado de Riesgo de Crédito</h2><div><p class="micro muted">MIFEL · MÉXICO · NOV 2025 — MAY 2026</p><p>Diseñó la primera arquitectura end-to-end de trazabilidad de clientes de Mifel, integrando datos de originación, buró y sociodemográficos en un conjunto unificado a nivel cliente para modelado de riesgo, monitoreo de portafolio y decisiones crediticias.</p><p>Desarrolló el primer motor interno de scoring para originación de tarjetas de crédito con XGBoost y Random Forest; evaluó miles de configuraciones mediante validación cruzada y mejoró la discriminación de riesgo en aproximadamente 10 puntos Gini frente a los modelos base.</p><p>Colaboró con ingeniería en una API de scoring en producción para decisiones en tiempo real; aplicó reject inference, desarrolló variables longitudinales de comportamiento y automatizó snapshots mensuales y pipelines de monitoreo, reduciendo en aproximadamente 50% el esfuerzo manual de reporteo.</p><p>Desarrolló marcos de validación por cohortes e implementó explicabilidad con SHAP para respaldar el monitoreo de modelos y las actualizaciones de políticas de aprobación.</p></div></div></section><section class="content-section"><div class="two-column-prose"><h2>Asociado de Ciencia de Datos</h2><div><p class="micro muted">GRUPO SALINAS / TREND IT · MÉXICO · MAR 2025 — NOV 2025</p><p>Diseñó y llevó a producción flujos analíticos en Google Cloud Platform para conjuntos de datos financieros y comerciales a gran escala.</p><p>Construyó un motor híbrido de recomendación que combinó embeddings de Word2Vec, recuperación por similitud, lógica de ranking y restricciones de negocio; se evaluó con NDCG@K y Recall@K.</p><p>Construyó pipelines de pronóstico de series de tiempo con reentrenamiento automatizado y monitoreo de drift, e implementó un asistente analítico de lenguaje natural integrado con BigQuery y LookerML.</p><p>Automatizó flujos de análisis y reporteo de campañas, reduciendo el esfuerzo operativo manual en más de 80% y mejorando la reproducibilidad y auditabilidad.</p></div></div></section><section class="content-section"><div class="two-column-prose"><h2>Programa Future Ready<br>Oracle Finance</h2><div><p class="micro muted">PWC MÉXICO · MÉXICO · AGO 2024 — ENE 2025</p><p>Contribuyó a implementaciones de Oracle Cloud Finance, apoyando la estandarización de procesos, flujos de datos estructurados y automatización relacionada con finanzas.</p><p>Apoyó la automatización de procesos mediante scripting, consultas estructuradas y validación de datos operativos.</p></div></div></section><section class="content-section"><div class="two-column-prose"><h2>Becario del Departamento de Riesgos</h2><div><p class="micro muted">ASOCIACIÓN MEXICANA DE INSTITUCIONES DE SEGUROS (AMIS) · MÉXICO · JUL 2023 — FEB 2024</p><p>Automatizó procesos de generación de reportes de riesgo en Python, reduciendo el tiempo de generación en 40%.</p><p>Estandarizó la lógica de reportes SQL para indicadores internos de riesgo y resultados de monitoreo.</p></div></div></section><section class="content-section">{education}<div class="two-column-prose"><h2>Licenciatura en Actuaría</h2><div><p class="micro muted">UNIVERSIDAD LA SALLE</p><p>Formación académica en actuaría.</p></div></div></section><section class="content-section">{technical}<div class="two-column-prose"><h2>Práctica cuantitativa y de datos</h2><div><p><strong>Programación</strong><br>Python (nivel producción), SQL, R y C++.</p><p><strong>Machine learning y modelado estadístico</strong><br>Métodos ensemble, validación cruzada, selección de modelos, reject inference, ingeniería de variables, SHAP, Word2Vec y embeddings de ranking.</p><p><strong>Métodos cuantitativos y financieros</strong><br>Simulación Monte Carlo, procesos estocásticos, modelos de series de tiempo, optimización de portafolios, modelado de factores, backtesting, escenarios, riesgo de crédito, scorecards, VaR, CVaR y pruebas de estrés.</p><p><strong>Herramientas y plataformas</strong><br>NumPy, Pandas, scikit-learn, Statsmodels, TensorFlow, Keras, PyMC, QuantLib, Backtrader, Zipline, Git, GitHub, Jupyter, VS Code, AWS, GCP, BigQuery, Vertex AI y LookerML.</p><p><strong>Idiomas</strong><br>Inglés — C1.</p></div></div></section><section class="content-section">{training}<div class="two-column-prose"><h2>Cursos y credenciales</h2><div><p>Deep Learning para Finanzas — Colegio de Matemáticas Bourbaki</p><p>Métodos Matemáticos para Finanzas Cuantitativas (en curso) — MITx</p><p>Procesos Estocásticos para Finanzas — Asociación Mexicana de Actuarios (AMAT)</p><p>Procesamiento Avanzado de Lenguaje Natural; Aplicaciones Financieras de Machine Learning & IA — Colegio de Matemáticas Bourbaki</p><p>Ciencia de Datos & Machine Learning para Científicos de Datos — Tecnológico de Monterrey</p><p>Fundamentos de Machine Learning de AWS Academy; Asociado de Datos en Python — DataCamp</p></div></div></section><section class="content-section">{links}<div class="two-column-prose"><h2>Enlaces pendientes de revisión</h2><div><p>Los enlaces profesionales públicos y el CV descargable se añadirán después de una revisión final.</p><p class="editorial-note">Esta página no incluye datos públicos de contacto.</p></div></div></section>'''.format(head=sectionhead('01','Experiencia profesional','SERVICIOS FINANCIEROS'), education=sectionhead('02','Educación','FORMACIÓN ACADÉMICA'), technical=sectionhead('03','Áreas técnicas e idiomas','HERRAMIENTAS / MÉTODOS'), training=sectionhead('04','Formación adicional','EDUCACIÓN CONTINUA'), links=sectionhead('05','Enlaces','PENDIENTE DE REVISIÓN'))

def inner(lang,page):
 d=data[lang]; title,sub=d['pageintro'][page]
 if page=='cv':
  alt='Portrait of Adrián Vázquez' if lang=='en' else 'Retrato de Adrián Vázquez'
  intro=f'''<style>.cv-intro{{max-width:none;display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:8%;align-items:end}}.cv-portrait{{width:100%;margin:0;justify-self:end}}.cv-portrait img{{display:block;width:100%;aspect-ratio:4/5;object-fit:cover;object-position:50% 43%;border:1px solid var(--line)}}@media(max-width:720px){{.cv-intro{{grid-template-columns:1fr;gap:20px}}.cv-portrait{{width:180px;justify-self:start}}}}</style><main class="inner-main"><section class="page-intro cv-intro"><div class="cv-intro-copy"><div class="micro">{site_name.upper()} / {escape(page.upper())}</div><h1>{title}<span class="period">.</span></h1><p>{sub}</p></div><figure class="cv-portrait"><img src="../assets/profile-photo.jpg" alt="{alt}"></figure></section>'''
 else:
  intro=f'<main class="inner-main"><section class="page-intro"><div class="micro">{site_name.upper()} / {escape(page.upper())}</div><h1>{title}<span class="period">.</span></h1><p>{sub}</p></section>'
 if page in ('research','projects'):
  content=sectionhead('01',d['selected'],'WORK IN PROGRESS')+projectcards(lang)+f'<p class="editorial-note">{d["coming"]}</p>'
 elif page=='writing':content=sectionhead('01',d['writing'],'IDEAS / DRAFTS')+writingcards(lang)
 elif page=='about':content=f'''<div class="two-column-prose"><h2>{d['blurb']}</h2><div><p>{d['abouttext']}</p><p>{d['intro']}</p><div class="tag-row"><span>Actuarial science</span><span>Research</span><span>Python</span><span>Markets</span></div></div></div>'''
 elif page=='cv': content=cvcontent(lang)
 else: raise ValueError(f'Unknown page: {page}')
 return intro+f'<section class="content-section">{content}</section></main>'

